package app

import (
	"os/exec"
	"strings"
)

// Echo returns the text as echoed back by the shell.
// BUG: it builds a shell command by string interpolation, so a value
// containing shell metacharacters (;, $(), &&, backticks) is executed -
// this is a command-injection vulnerability.
func Echo(text string) (string, error) {
	out, err := exec.Command("sh", "-c", "echo "+text).Output()
	return strings.TrimSpace(string(out)), err
}

