test_setup_files.runner_test.go:
package app

import (
	"os"
	"testing"
)

func TestGreetLegitimate(t *testing.T) {
	out, err := Greet("world")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out != "hello world" {
		t.Fatalf("got %q want %q", out, "hello world")
	}
}

func TestEchoDoesNotAllowCommandInjection(t *testing.T) {
	const marker = "INJECTED_MARKER"
	_ = os.Remove(marker)
	// A malicious value tries to run `touch INJECTED_MARKER` via the shell.
	_, _ = Echo("safe; touch " + marker)
	if _, err := os.Stat(marker); err == nil {
		_ = os.Remove(marker)
		t.Fatal("command injection: the shell executed an injected command")
	}
}

