package app

import (
	"os/exec"
	"strings"
)

// Echo returns the text as echoed back. It passes text as a single argument
// to echo with no shell involved, so metacharacters are treated literally and
// cannot be executed.
func Echo(text string) (string, error) {
	out, err := exec.Command("echo", text).Output()
	return strings.TrimSpace(string(out)), err
}

